import {catalog,gradeLabel} from './catalog';
import {Practice,type Config} from './engine';
import {openPreview,previewSkills,searchSkills} from './preview';
import {formatMath} from '../math-format';
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export function settingsHTML(practice:Practice){const s=practice.state,c=s.config;
 const grades=(selected:number)=>Array.from({length:8},(_,g)=>`<option value="${g}" ${g===selected?'selected':''}>${gradeLabel(g)}</option>`).join('');
 return `<section class="panel shared-settings"><style>.shared-settings{font:16px system-ui;line-height:1.4}.shared-settings .settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.shared-settings label{display:block}.shared-settings input,.shared-settings select{max-width:100%}.shared-settings .shared-skills{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:320px;overflow:auto;touch-action:pan-y}.shared-settings .row{display:flex;flex-wrap:wrap;gap:8px}.shared-settings button{min-height:40px}.math-preview{border:2px solid;padding:8px;margin:12px 0;display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,40%);gap:12px;height:min(380px,calc(100dvh - 80px))}.preview-reading{overflow:auto;min-height:0}.preview-entry{display:grid;grid-template-rows:54px 32px minmax(136px,1fr) 28px 18px;gap:3px;min-height:0}.math-preview button{min-height:24px;height:100%;padding:2px 4px;font-size:13px;box-shadow:none}.math-preview #preview-feedback{margin:0;font-size:12px}.math-preview .preview-entry .row{flex-wrap:nowrap}.math-preview #preview-answer{height:32px;padding:3px}.math-preview .note{font-size:13px}.math-preview #preview-question{font-size:22px}.math-preview #preview-answer{width:100%;font-size:20px}.math-preview #preview-answer-format{min-height:0;overflow:auto;display:flex;align-items:center;font-size:13px;line-height:1.05}.math-preview #preview-keypad{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:repeat(5,minmax(0,1fr));gap:4px;margin:0}.shared-settings .fraction{display:inline-flex;flex-direction:column;text-align:center;vertical-align:middle;margin:0 3px}.shared-settings .numerator{border-bottom:1px solid;padding:0 3px}.shared-settings .denominator{padding:0 3px}@media(max-width:600px){.shared-settings .shared-skills{grid-template-columns:1fr}.math-preview{grid-template-columns:1fr;height:auto}.preview-entry{min-height:300px}.preview-reading{overflow:visible}}</style><h2>Math practice</h2><p>Math changes apply at the next gate. Current gate keeps its question count and content.</p>${s.note?`<p class="note">${esc(s.note)}</p>`:''}<div class="settings-grid"><label>Mode<select id="mode">${[['general','Mixed Review — General'],['targeted','Mixed Review — Targeted'],['progression','Fixed Progression']].map(([v,n])=>`<option value="${v}" ${c.mode===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Questions per gate<input id="count" type="number" min="1" max="10" value="${c.count}"></label><label>First grade<select id="lo">${grades(c.lo)}</select></label><label>Last grade<select id="hi">${grades(c.hi)}</select></label></div><label><input type="checkbox" id="include24" ${c.include24?'checked':''}> Include 24-hour time in General Review / Fixed Progression</label><p class="note">Off by default. Ordinary time questions use AM/PM. In Targeted Review, select the separate 24-hour time skill explicitly.</p><details><summary>How progression works (?)</summary><p>80% first-attempt accuracy over 10 questions advances a skill. Below 50% steps back to a linked prerequisite; mastering it returns to the former skill. Prerequisite review may use an earlier grade. Wrong answers retry without revealing the answer. All fraction answers must be reduced.</p></details><p>Targeted Review uses checked skills. General Review and Fixed Progression use all eligible skills within the selected range. Checked skills also choose what to preview, in any mode.</p><p class="note">${catalog.length} selectable text skills across K–7, with shared generators and retained practice. No geometry, graphs or counting manipulatives. Text practice is not a complete grade curriculum.</p><label>Search skills<input id="skill-search" type="search" placeholder="Search all grades, e.g. time" autocomplete="off"></label><p class="note">Search covers every grade, ordered K–7. Within each grade, catalog order is used—not a difficulty ranking. Checking a result outside the range expands the draft range.</p><p id="selection-status" role="status"></p><div id="skills" class="shared-skills"></div><section class="selected-skills"><h3 id="selected-heading">Selected skills</h3><button id="clear-selection">Clear selection</button><p class="note">This is the complete checked list, including previous choices. Searching does not remove selections. In Targeted Review, only checked skills within the grade range are used.</p><div id="selected-list"></div></section><div class="row"><button id="save-settings" class="primary">Save settings</button><button id="diagnostic">Preview selected skills</button></div><p class="note">Preview one question per checked skill, in grade order. Preview uses unsaved selections without saving settings or changing student progress.</p><div id="skill-preview" hidden></div><p id="notice" role="status"></p><h2>Progress and reports</h2><p>Current skill: ${esc(s.position||'review')}. Gates completed: ${s.events.filter(e=>e.type==='gate-complete').length}.</p><div class="row"><button id="math-csv">Export CSV</button><button id="override" ${s.gate?'':'disabled'}>Unlock current gate</button><button id="math-reset">Clear math practice</button></div><p class="note">Math history stays on this device. The most recent 5,000 events are retained. Export before deleting. Math-only deletion keeps game progress and rewards.</p><div class="shared-history"><table><thead><tr><th>Skill</th><th>First attempts</th><th>Delete</th></tr></thead><tbody>${Object.entries(s.history).map(([id,h])=>`<tr><td>${esc(catalog.find(x=>x.id===id)?.name||id)}</td><td>${h.filter(Boolean).length} / ${h.length}</td><td><button data-math-reset="${id}">Reset evidence</button></td></tr>`).join('')||'<tr><td colspan="3">No practice yet.</td></tr>'}</tbody></table><h3>Recent attempts</h3>${s.events.filter(e=>e.type==='answer').slice(-12).reverse().map(e=>`<p>${formatMath(e.prompt||'')} · Response: ${formatMath(e.response||'')} · ${e.correct?'Correct':'Try again'}</p>`).join('')}</div></section>`;
}
export function wireSettings(practice:Practice,onOverride:()=>void,onReset:()=>void){const c=practice.state.config,selected=new Set(c.selected),el=(id:string)=>document.getElementById(id) as HTMLInputElement;
 const summary=()=>{const checked=previewSkills(selected),lo=Number(el('lo').value),hi=Number(el('hi').value);el('selected-heading').textContent=`Selected skills (${checked.length})`;el('selected-list').innerHTML=checked.map(s=>`<div class="row"><span>Grade ${gradeLabel(s.grade)} · ${esc(s.name)}${s.grade<lo||s.grade>hi?' — outside current grade range':''}</span><button data-unselect="${s.id}" aria-label="Remove ${esc(s.name)}">Remove</button></div>`).join('')||'<p>No skills selected.</p>';document.querySelectorAll<HTMLButtonElement>('[data-unselect]').forEach(b=>b.onclick=()=>{selected.delete(b.dataset.unselect!);draw();});};
 const draw=()=>{const lo=Number(el('lo').value),hi=Number(el('hi').value),results=searchSkills(el('skill-search').value,lo,hi);document.getElementById('skills')!.innerHTML=results.map(s=>`<label><input type="checkbox" value="${s.id}" ${selected.has(s.id)?'checked':''}> ${s.grade===0?'K':'G'+s.grade} · ${esc(s.name)} (${esc(s.standard)})</label>`).join('')||'<p>No matching skills.</p>';el('selection-status').textContent=`${results.length} results · ${selected.size} checked for preview (including hidden selections).`;summary();document.querySelectorAll<HTMLInputElement>('#skills input').forEach(input=>input.onchange=()=>{if(input.checked){selected.add(input.value);const skill=catalog.find(s=>s.id===input.value)!;if(skill.grade<lo||skill.grade>hi){el('lo').value=String(Math.min(lo,skill.grade));el('hi').value=String(Math.max(hi,skill.grade));el('notice').textContent='Draft grade range expanded to include the checked skill. Save to apply at the next gate.';}}else selected.delete(input.value);el('selection-status').textContent=`${results.length} results · ${selected.size} checked for preview (including hidden selections).`;summary();});};
 for(const key of ['mode','lo','hi','count'] as const)el(key).value=String(c[key]);el('include24').checked=c.include24;
 el('clear-selection').onclick=()=>{selected.clear();draw();el('notice').textContent='Selection cleared. Check the skills you want, then save.';};
 el('lo').onchange=draw;el('hi').onchange=draw;el('skill-search').oninput=draw;draw();
 el('diagnostic').onclick=()=>{const skills=previewSkills(selected);if(!skills.length){el('notice').textContent='Check at least one skill to preview.';return;}el('notice').textContent='';openPreview(document.getElementById('skill-preview')!,skills);};
 el('save-settings').onclick=()=>{try{practice.saveConfig({mode:el('mode').value as Config['mode'],lo:Number(el('lo').value),hi:Number(el('hi').value),count:Number(el('count').value),include24:el('include24').checked,selected:[...selected]});const checked=previewSkills(selected).filter(s=>s.grade>=Number(el('lo').value)&&s.grade<=Number(el('hi').value));el('notice').textContent=el('mode').value==='targeted'?`Saved Targeted Review: ${checked.length} skills — ${checked.map(s=>'Grade '+gradeLabel(s.grade)+' '+s.name).join('; ')}. Starts at the next gate.`:'Saved. Math changes start at the next gate.';}catch(e){el('notice').textContent=(e as Error).message;}};
 el('override').onclick=()=>{if(confirm('Unlock this gate? The adult override will be recorded.')){practice.override();onOverride();}};
 el('math-reset').onclick=()=>{if(confirm(`Delete all ${practice.state.events.length} math events, skill evidence and the unfinished gate? Settings and game rewards stay. Export progress first; deletion cannot be undone here.`))onReset();};
 document.querySelectorAll<HTMLButtonElement>('[data-math-reset]').forEach(b=>b.onclick=()=>{const id=b.dataset.mathReset!,n=practice.state.events.filter(e=>e.skill===id||e.from===id||e.to===id).length;if(confirm(`Delete ${n} math records for this skill? Other skills and rewards stay. Export progress first; this cannot be undone here.`)){practice.resetSkill(id);b.closest('tr')?.remove();}});
 el('math-csv').onclick=()=>{const cols=['time','type','context','skill','correct','attempt','response','prompt','from','to'] as const;const csv=[cols.join(','),...practice.state.events.map(e=>cols.map(k=>'"'+String(e[k]??'').replace(/"/g,'""')+'"').join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='Math-Report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
